// Dolce+ — Apple Wallet loyalty card (real version).
//
// One card per client. It shows the client's name, D+ points, level and a QR
// code (an opaque member code — no phone, email or other personal data).
// The card's colour follows the level: Member = ivory, Gold = gold, Black = black.
// When points, level or name change, the database calls /notify and this
// function pushes the update to every iPhone that holds the card.
//
// Endpoints
//   POST /card                 (client app, Authorization: Bearer <client login>)
//        body {client_id?}     → { url } short-lived link to download the card
//   GET  /download/:serial?e=&s=   signed link (15 min) → the .pkpass file
//   POST /notify  {serial}     database trigger → push update (only if the card
//                              really changed in the last 15 minutes)
//   Apple Wallet web service (called by the iPhone, "ApplePass <token>"):
//   POST/DELETE /v1/devices/:dev/registrations/:ptid/:serial
//   GET         /v1/devices/:dev/registrations/:ptid?passesUpdatedSince=…
//   GET         /v1/passes/:ptid/:serial
//   POST        /v1/log
//
// Secrets (Supabase → Edge Functions → Secrets). Never in Git, the app or chat.
//   WALLET_CERT_B64, WALLET_KEY_B64   Pass Type ID certificate + key (PEM, base64)
//   WALLET_PASS_TYPE_ID, WALLET_TEAM_ID
//   WALLET_SECRET                     long random string (signs links + card tokens)
//   (Until those are added, the WALLET_TEST_* secrets from the feasibility test
//    are used. Add the WALLET_* copies BEFORE removing the test secrets.)
// Provided automatically: SUPABASE_URL, SUPABASE_ANON_KEY, SUPABASE_SERVICE_ROLE_KEY.
// Deploy with "Verify JWT" OFF — /card checks the client login itself, and
// Apple's calls carry their own ApplePass token.

import forge from "npm:node-forge@1.3.1";
import { zipSync } from "npm:fflate@0.8.2";

const env = (k: string) => Deno.env.get(k) ?? "";
const sec = (k: string) => env("WALLET_" + k) || env("WALLET_TEST_" + k);
const SECRET = () => env("WALLET_SECRET") || env("WALLET_TEST_ADMIN_KEY");
const APP_URL = () => env("WALLET_APP_URL") || "https://dolce-plus.github.io/Dolce/";
const APP_STORE_ID = 6827982047;
const WWDR_URL = "https://www.apple.com/certificateauthority/AppleWWDRCAG4.cer";

const BUSINESS = {
  name: "Dolce Aesthetic Clinic",
  address: "Park View, Naz Naz, Erbil, Kurdistan Region, Iraq",
  phone: "+964 750 900 0200",
  email: "hello@dolceclinic.com",
  web: "https://dolceclinic.com",
};
const TIERS: Record<string, { bg: string; fg: string; label: string; name: string }> = {
  member: { bg: "rgb(248,241,230)", fg: "rgb(58,42,31)",   label: "rgb(140,105,52)",  name: "D+ Member" },
  gold:   { bg: "rgb(201,164,106)", fg: "rgb(43,31,20)",   label: "rgb(84,60,30)",    name: "D+ Gold" },
  black:  { bg: "rgb(18,18,18)",    fg: "rgb(245,239,228)", label: "rgb(201,164,106)", name: "D+ Black" },
};

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
const json = (s: number, b: unknown, extra: Record<string, string> = {}) =>
  new Response(JSON.stringify(b), { status: s, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...extra } });
const empty = (s: number) => new Response(null, { status: s });

// ---------- helpers ----------
const enc = new TextEncoder();
function b64pem(name: string): string {
  const v = sec(name).replace(/\s+/g, "");
  if (!v) throw new Error(`missing secret WALLET_${name}`);
  try { return atob(v); } catch { throw new Error(`secret WALLET_${name} is not valid base64`); }
}
export function safeEqual(a: string, b: string): boolean {
  if (!a || !b || a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
async function hmacHex(key: string, msg: string): Promise<string> {
  const k = await crypto.subtle.importKey("raw", enc.encode(key), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", k, enc.encode(msg)));
  return [...sig].map((x) => x.toString(16).padStart(2, "0")).join("");
}
async function sha1Hex(bytes: Uint8Array): Promise<string> {
  const d = new Uint8Array(await crypto.subtle.digest("SHA-1", bytes as BufferSource));
  return [...d].map((x) => x.toString(16).padStart(2, "0")).join("");
}
function need(v: string, what: string) { if (!v) throw new Error(`missing ${what}`); return v; }
// The card's ApplePass token: derived from the serial with the server secret
// (nothing stored, never changes for a card).
export const passToken = async (serial: string) => (await hmacHex(need(SECRET(), "WALLET_SECRET") + "|apple-pass", serial)).slice(0, 40);
const linkSig = async (serial: string, e: number) => (await hmacHex(need(SECRET(), "WALLET_SECRET") + "|download", `${serial}|${e}`)).slice(0, 32);
const short = (t: string) => (t ? t.slice(0, 6) + "…" + t.slice(-4) : "");
const SERIAL_RE = /^W[2-9A-HJ-NP-Z]{16}$/;
export const prettyCode = (c: string) => `${c.slice(0, 2)}-${c.slice(2, 7)}-${c.slice(7)}`;

// ---------- database (service role) ----------
async function db(path: string, init: RequestInit = {}) {
  const key = env("SUPABASE_SERVICE_ROLE_KEY");
  const r = await fetch(`${env("SUPABASE_URL")}/rest/v1/${path}`, {
    ...init,
    headers: { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json", Prefer: "return=representation", ...(init.headers || {}) },
  });
  const text = await r.text();
  if (!r.ok) throw new Error(`db ${r.status}: ${text.slice(0, 200)}`);
  return text ? JSON.parse(text) : null;
}
async function card(serial: string) {
  const rows = await db(`wallet_cards?serial=eq.${encodeURIComponent(serial)}&select=*`);
  return rows?.[0] || null;
}
async function logEvent(kind: string, detail: unknown) {
  try { await db("wallet_log", { method: "POST", body: JSON.stringify({ kind, detail }), headers: { Prefer: "return=minimal" } }); } catch { /* never fail over a log row */ }
}

// ---------- certificates ----------
let wwdrPem = "";
async function wwdr(): Promise<string> {
  if (wwdrPem) return wwdrPem;
  if (sec("WWDR_B64")) { wwdrPem = b64pem("WWDR_B64"); return wwdrPem; }
  const r = await fetch(WWDR_URL);
  if (!r.ok) throw new Error(`could not download Apple WWDR G4 (${r.status})`);
  const der = new Uint8Array(await r.arrayBuffer());
  let bin = ""; for (const b of der) bin += String.fromCharCode(b);
  const cert = forge.pki.certificateFromAsn1(forge.asn1.fromDer(bin));
  const cn = cert.subject.getField("CN")?.value || "", ou = cert.subject.getField("OU")?.value || "";
  if (!/Apple Worldwide Developer Relations/.test(cn) || ou !== "G4") throw new Error("unexpected WWDR certificate");
  wwdrPem = forge.pki.certificateToPem(cert);
  return wwdrPem;
}

// ---------- the card ----------
function b64bytes(b: string) { const s = atob(b); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
function memberSince(d: string | null) {
  if (!d) return "";
  const x = new Date(d + "T00:00:00Z");
  return isNaN(x.getTime()) ? "" : x.toLocaleString("en-US", { month: "short", year: "numeric", timeZone: "UTC" });
}

export function passJson(c: Record<string, any>, token: string) {
  const t = TIERS[c.tier] || TIERS.member;
  const fields: Record<string, unknown[]> = {
    headerFields: [{ key: "points", label: "POINTS", value: Number(c.points) || 0, numberStyle: "PKNumberStyleDecimal",
      changeMessage: "You now have %@ D+ points" }],
    primaryFields: [{ key: "name", label: "NAME", value: c.name || "Dolce+ Member" }],
    secondaryFields: [{ key: "level", label: "LEVEL", value: t.name, changeMessage: "Your Dolce+ level is now %@" }],
    auxiliaryFields: memberSince(c.member_since)
      ? [{ key: "since", label: "MEMBER SINCE", value: memberSince(c.member_since), textAlignment: "PKTextAlignmentRight" }] : [],
    backFields: [
      { key: "how", label: "How to use", value: "Show this card at reception at Dolce, Polished or CORE. Staff scan the code to see your points and rewards." },
      { key: "about", label: "D+ points", value: "You earn points on visits and purchases and spend them on rewards. Your level (Member, Gold, Black) depends on what you spent in the last 12 months. Points have no cash value." },
      { key: "code", label: "Member code", value: prettyCode(c.member_code) },
      { key: "business", label: BUSINESS.name, value: BUSINESS.address },
      { key: "phone", label: "Phone / WhatsApp", value: BUSINESS.phone, dataDetectorTypes: ["PKDataDetectorTypePhoneNumber"] },
      { key: "email", label: "Email", value: BUSINESS.email },
      { key: "web", label: "Website", value: BUSINESS.web, dataDetectorTypes: ["PKDataDetectorTypeLink"] },
      { key: "updated", label: "Last updated", value: new Date(c.updated_at).toISOString(), dateStyle: "PKDateStyleMedium", timeStyle: "PKDateStyleShort" },
    ],
  };
  return {
    formatVersion: 1,
    passTypeIdentifier: need(sec("PASS_TYPE_ID"), "WALLET_PASS_TYPE_ID"),
    serialNumber: c.serial,
    teamIdentifier: need(sec("TEAM_ID"), "WALLET_TEAM_ID"),
    organizationName: "Dolce+",
    description: "Dolce+ membership card",
    foregroundColor: t.fg, backgroundColor: t.bg, labelColor: t.label,
    webServiceURL: `${env("SUPABASE_URL")}/functions/v1/wallet`,
    authenticationToken: token,
    associatedStoreIdentifiers: [APP_STORE_ID],
    sharingProhibited: true,
    storeCard: fields,
    barcodes: [{ format: "PKBarcodeFormatQR", message: `${APP_URL()}?m=${c.member_code}#admin`, messageEncoding: "iso-8859-1", altText: prettyCode(c.member_code) }],
  };
}

export async function buildPass(c: Record<string, any>): Promise<Uint8Array> {
  const tier = TIERS[c.tier] ? c.tier : "member";
  const pass = passJson(c, await passToken(c.serial));
  const files: Record<string, Uint8Array> = { "pass.json": enc.encode(JSON.stringify(pass)) };
  for (const n of ["icon.png", "icon@2x.png", "icon@3x.png"]) files[n] = b64bytes(IMG[n]);
  for (const s of ["@2x", "@3x"]) {
    files[`logo${s}.png`] = b64bytes(IMG[`logo-${tier}${s}.png`]);
    files[`strip${s}.png`] = b64bytes(IMG[`strip-${tier}${s}.png`]);
  }
  const manifest: Record<string, string> = {};
  for (const [n, b] of Object.entries(files)) manifest[n] = await sha1Hex(b);
  const manifestStr = JSON.stringify(manifest);
  files["manifest.json"] = enc.encode(manifestStr);

  const cert = forge.pki.certificateFromPem(b64pem("CERT_B64"));
  const key = forge.pki.privateKeyFromPem(b64pem("KEY_B64"));
  const p7 = forge.pkcs7.createSignedData();
  p7.content = forge.util.createBuffer(manifestStr, "utf8");
  p7.addCertificate(cert);
  p7.addCertificate(forge.pki.certificateFromPem(await wwdr()));
  p7.addSigner({
    key, certificate: cert, digestAlgorithm: forge.pki.oids.sha256,
    authenticatedAttributes: [
      { type: forge.pki.oids.contentType, value: forge.pki.oids.data },
      { type: forge.pki.oids.messageDigest },
      { type: forge.pki.oids.signingTime, value: new Date() as any },
    ],
  });
  p7.sign({ detached: true });
  files["signature"] = b64bytes(forge.util.encode64(forge.asn1.toDer(p7.toAsn1()).getBytes()));
  return zipSync(files, { level: 6 });
}
function pkpassResponse(bytes: Uint8Array, lastModified: string) {
  return new Response(bytes as BodyInit, {
    status: 200,
    headers: {
      "Content-Type": "application/vnd.apple.pkpass",
      "Content-Disposition": `attachment; filename="DolcePlus.pkpass"`,
      "Last-Modified": new Date(lastModified).toUTCString(),
      "Cache-Control": "no-store",
    },
  });
}

// ---------- APNs (Wallet update push: empty payload, topic = pass type ID) ----------
async function apnsPush(token: string) {
  const certPem = b64pem("CERT_B64"), keyPem = b64pem("KEY_B64");
  const headers: Record<string, string> = { "apns-topic": need(sec("PASS_TYPE_ID"), "WALLET_PASS_TYPE_ID") };
  const attempts: Record<string, unknown>[] = [];
  try {
    const create = (Deno as any).createHttpClient;
    if (typeof create !== "function") throw new Error("Deno.createHttpClient unavailable");
    const client = create({ cert: certPem, key: keyPem });
    const r = await fetch(`https://api.push.apple.com/3/device/${token}`, { method: "POST", headers, body: "{}", client } as any);
    const body = await r.text();
    attempts.push({ via: "fetch", status: r.status, body: body.slice(0, 120) });
    try { client.close(); } catch { /* ignore */ }
    if (r.status === 200) return { ok: true, attempts };
  } catch (e) { attempts.push({ via: "fetch", error: String((e as Error).message || e).slice(0, 160) }); }
  try {
    const http2: any = await import("node:http2");
    const res = await new Promise<Record<string, unknown>>((resolve, reject) => {
      const t = setTimeout(() => reject(new Error("timeout after 15s")), 15000);
      const s = http2.connect("https://api.push.apple.com", { cert: certPem, key: keyPem });
      s.on("error", (err: Error) => { clearTimeout(t); reject(err); });
      const req = s.request({ ":method": "POST", ":path": `/3/device/${token}`, ...headers, "content-type": "application/json" });
      let status = 0, data = "";
      req.on("response", (h: any) => { status = Number(h[":status"]); });
      req.setEncoding("utf8");
      req.on("data", (c: string) => (data += c));
      req.on("end", () => { clearTimeout(t); s.close(); resolve({ status, body: data.slice(0, 120) }); });
      req.on("error", (err: Error) => { clearTimeout(t); s.close(); reject(err); });
      req.end("{}");
    });
    attempts.push({ via: "http2", ...res });
    if (res.status === 200) return { ok: true, attempts };
  } catch (e) { attempts.push({ via: "http2", error: String((e as Error).message || e).slice(0, 160) }); }
  return { ok: false, attempts };
}

// ---------- client login check (the client's own Supabase session) ----------
async function myClientIds(authHeader: string): Promise<string[] | null> {
  const r = await fetch(`${env("SUPABASE_URL")}/rest/v1/rpc/my_client_ids`, {
    method: "POST",
    headers: { apikey: env("SUPABASE_ANON_KEY"), Authorization: authHeader, "Content-Type": "application/json" },
    body: "{}",
  });
  if (r.status === 401 || r.status === 403) return null;
  if (!r.ok) throw new Error(`login check ${r.status}`);
  const ids = await r.json();
  return Array.isArray(ids) ? ids.map(String) : [];
}

// ---------- routing ----------
export async function handle(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const path = url.pathname.replace(/^.*?\/wallet(?=\/|$)/, "") || "/";
  const ptid = sec("PASS_TYPE_ID");
  const appleOk = async (serial: string) => {
    const h = req.headers.get("authorization") || "";
    return h.startsWith("ApplePass ") && safeEqual(h.slice(10).trim(), await passToken(serial));
  };

  try {
    // ----- client app: get my card -----
    if (path === "/card") {
      if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
      if (req.method !== "POST") return json(405, { error: "method" }, CORS);
      const auth = req.headers.get("authorization") || "";
      if (!/^Bearer \S+/.test(auth)) return json(401, { error: "LOGIN_NEEDED" }, CORS);
      const ids = await myClientIds(auth);
      if (ids === null) return json(401, { error: "LOGIN_NEEDED" }, CORS);
      const body = await req.json().catch(() => ({}));
      const want = body?.client_id ? String(body.client_id) : "";
      const cid = want ? (ids.includes(want) ? want : "") : (ids[0] || "");
      if (!cid) return json(want ? 403 : 404, { error: want ? "NOT_YOURS" : "NO_ACCOUNT" }, CORS);
      const c = await db("rpc/wallet_issue_card", { method: "POST", body: JSON.stringify({ cid }) });
      const row = Array.isArray(c) ? c[0] : c;
      if (!row?.serial) throw new Error("card not created");
      const e = Math.floor(Date.now() / 1000) + 900;
      const link = `${env("SUPABASE_URL")}/functions/v1/wallet/download/${row.serial}?e=${e}&s=${await linkSig(row.serial, e)}`;
      await logEvent("card_link", { serial: short(row.serial) });
      return json(200, { url: link, tier: row.tier, points: row.points }, CORS);
    }

    // ----- signed download (opened in Safari → "Add to Apple Wallet") -----
    let m: RegExpMatchArray | null;
    if (req.method === "GET" && (m = path.match(/^\/download\/([^/]+)$/))) {
      const serial = m[1], e = Number(url.searchParams.get("e") || "0"), s = url.searchParams.get("s") || "";
      if (!SERIAL_RE.test(serial) || !e || e < Date.now() / 1000 || !safeEqual(s, await linkSig(serial, e))) {
        return new Response("This link has expired. Please tap \"Add to Apple Wallet\" in the Dolce+ app again.", { status: 403, headers: { "Content-Type": "text/plain; charset=utf-8" } });
      }
      const c = await card(serial);
      if (!c) return empty(404);
      await db("rpc/wallet_refresh", { method: "POST", body: JSON.stringify({ cid: c.client_id, p_notify: false }) }).catch(() => null);
      const fresh = (await card(serial)) || c;
      const bytes = await buildPass(fresh);
      await logEvent("pass_download", { serial: short(serial), by: "link" });
      return pkpassResponse(bytes, fresh.updated_at);
    }

    // ----- database: something on this card changed → push -----
    if (req.method === "POST" && path === "/notify") {
      const body = await req.json().catch(() => ({}));
      const serial = String(body?.serial || "");
      if (!SERIAL_RE.test(serial)) return empty(400);
      const c = await card(serial);
      if (!c) return json(200, { skipped: "no card" });
      const upd = new Date(c.updated_at).getTime();
      if (c.pushed_at && new Date(c.pushed_at).getTime() >= upd) return json(200, { skipped: "already pushed" });
      if (Date.now() - upd > 15 * 60 * 1000) return json(200, { skipped: "old change" });
      const regs = await db(`wallet_registrations?serial=eq.${serial}&select=device_id,push_token`);
      await db(`wallet_cards?serial=eq.${serial}`, { method: "PATCH", body: JSON.stringify({ pushed_at: new Date().toISOString() }), headers: { Prefer: "return=minimal" } });
      const results = [];
      for (const r of regs || []) {
        const res = await apnsPush(r.push_token);
        results.push({ device: short(r.device_id), ok: res.ok, via: res.attempts.map((a: any) => a.via + ":" + (a.status ?? "err")).join(",") });
        if (res.attempts.some((a: any) => a.status === 410 || /BadDeviceToken|Unregistered/.test(String(a.body || "")))) {
          await db(`wallet_registrations?device_id=eq.${encodeURIComponent(r.device_id)}&serial=eq.${serial}`, { method: "DELETE" });
        }
      }
      await logEvent("push", { serial: short(serial), results });
      return json(200, { pushed: results.length });
    }

    // ----- Apple Wallet web service -----
    if ((m = path.match(/^\/v1\/devices\/([^/]+)\/registrations\/([^/]+)\/([^/]+)$/))) {
      const [, dev, pt, serial] = m;
      if (pt !== ptid || !SERIAL_RE.test(serial)) return empty(404);
      if (!(await appleOk(serial))) { await logEvent("auth_rejected", { path: "registration" }); return empty(401); }
      if (req.method === "POST") {
        if (!(await card(serial))) return empty(401);
        const body = await req.json().catch(() => ({}));
        const pushToken = String(body?.pushToken || "");
        if (!/^[0-9a-fA-F]{32,200}$/.test(pushToken) || dev.length > 200) return empty(400);
        const existing = await db(`wallet_registrations?device_id=eq.${encodeURIComponent(dev)}&serial=eq.${serial}&select=device_id`);
        await db(`wallet_registrations?on_conflict=device_id,pass_type_id,serial`, {
          method: "POST", body: JSON.stringify({ device_id: dev, pass_type_id: pt, serial, push_token: pushToken }),
          headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
        });
        await logEvent("device_registered", { serial: short(serial), device: short(dev), isNew: !existing?.length });
        return empty(existing?.length ? 200 : 201);
      }
      if (req.method === "DELETE") {
        await db(`wallet_registrations?device_id=eq.${encodeURIComponent(dev)}&serial=eq.${serial}`, { method: "DELETE" });
        await logEvent("device_unregistered", { serial: short(serial), device: short(dev) });
        return empty(200);
      }
      return empty(405);
    }
    if (req.method === "GET" && (m = path.match(/^\/v1\/devices\/([^/]+)\/registrations\/([^/]+)$/))) {
      const [, dev, pt] = m;
      if (pt !== ptid) return empty(404);
      const regs = await db(`wallet_registrations?device_id=eq.${encodeURIComponent(dev)}&pass_type_id=eq.${encodeURIComponent(pt)}&select=serial`);
      if (!regs?.length) return empty(404);
      const serials = regs.map((r: any) => r.serial).filter((s: string) => SERIAL_RE.test(s));
      const cards = serials.length ? await db(`wallet_cards?serial=in.(${serials.join(",")})&select=serial,updated_at`) : [];
      const since = Number(url.searchParams.get("passesUpdatedSince") || "0");
      const changed = (cards || []).filter((c: any) => !since || new Date(c.updated_at).getTime() > since);
      if (!changed.length) return empty(204);
      const last = Math.max(...changed.map((c: any) => new Date(c.updated_at).getTime()));
      return json(200, { serialNumbers: changed.map((c: any) => c.serial), lastUpdated: String(last) });
    }
    if (req.method === "GET" && (m = path.match(/^\/v1\/passes\/([^/]+)\/([^/]+)$/))) {
      const [, pt, serial] = m;
      if (pt !== ptid || !SERIAL_RE.test(serial)) return empty(404);
      if (!(await appleOk(serial))) { await logEvent("auth_rejected", { path: "pass" }); return empty(401); }
      const c = await card(serial);
      if (!c) return empty(404);
      const ims = req.headers.get("if-modified-since");
      if (ims && Math.floor(new Date(c.updated_at).getTime() / 1000) <= Math.floor(new Date(ims).getTime() / 1000)) return empty(304);
      const bytes = await buildPass(c);
      await logEvent("pass_download", { serial: short(serial), by: "wallet", tier: c.tier });
      return pkpassResponse(bytes, c.updated_at);
    }
    if (req.method === "POST" && path === "/v1/log") {
      const body = await req.json().catch(() => ({}));
      await logEvent("wallet_log", { logs: (body?.logs || []).slice(0, 10).map((s: unknown) => String(s).slice(0, 300)) });
      return empty(200);
    }
    return empty(404);
  } catch (e) {
    const msg = String((e as Error).message || e);
    await logEvent("error", { path: path.replace(/[0-9a-f]{20,}/gi, "…"), msg: msg.slice(0, 300) });
    return json(500, { error: "SERVER" }, path === "/card" ? CORS : {});
  }
}

Deno.serve(handle);

// ============================================================================
